    'RegisterSimpleRisk'=>'SimpleRisk 등록',
    'RegistrationText'=>'등록된 SimpleRisk 인스턴스는 업그레이드 및 Secure Controls Framework(SCF) Extra를 즉시 이용할 수 있습니다.  업그레이드 Extra를 사용하면 버튼 클릭 한 번으로 SimpleRisk 인스턴스를 백업하고 업그레이드할 수 있습니다.  Secure Controls Framework(SCF) Extra는 SimpleRisk 거버넌스 기능에 통합된 공통 제어 프레임워크를 제공합니다.  SimpleRisk를 등록하면 등록 정보가 SimpleRisk에서 호스팅하는 서버로 전송됩니다.  제공된 등록 정보는 SimpleRisk가 고객에게 새 릴리스 및 보안 업데이트를 알리는 데 사용됩니다.  SimpleRisk를 등록하면 마케팅 커뮤니케이션 수신에 동의하게 되지만, 해당 커뮤니케이션의 수신 거부 링크를 사용하여 언제든지 수신을 거부할 수 있습니다.  SimpleRisk는 고객의 개인정보를 존중하며, SimpleRisk 등록 과정을 통해 제공된 정보는 제3자에게 절대 판매되지 않습니다.',
