    'ExtrasDesc'                          => 'SimpleRisk Extras(유료 추가 기능)를 활성화, 비활성화 및 구성합니다.',
    'ArtificialIntelligenceExtraDesc'     => '인공지능 Extra는 향상된 위험 분석(FAIR 평가 포함)과 맞춤형 문서화를 제공합니다.',
    'CustomizationExtraDesc'              => '사용자 지정 Extra를 사용하면 다양한 유형의 필드를 추가 및 제거하고 사용자 지정 페이지 템플릿을 동적으로 생성할 수 있습니다.',
    'NotificationExtraDesc'               => '이메일 알림 Extra를 사용하면 위험이 제출, 수정되거나 기타 조치가 취해질 때 SimpleRisk가 이메일 알림을 보낼 수 있습니다. 이 Extra는 위험이 관리 검토 준비가 되었을 때 정기 알림을 보내는 예약된 스크립트로도 추가할 수 있습니다. 이 Extra가 없는 SimpleRisk Core 제품에서는 도구 외부로 알림이 전달되지 않습니다.',
    'VulnerabilityManagementExtraDesc'    => '취약점 관리 추가 기능을 통해 고객은 SimpleRisk 인스턴스를 Qualys, Tenable.io 또는 Rapid7 Nexpose/InsightVM과 통합하고 자산 및 취약점 데이터를 SimpleRisk로 가져올 수 있습니다. 이후, 관리할 사이트를 선택하고, 가져올 취약점 점수를 결정하며, 추적할 위험으로 분류할 취약점을 선별할 수 있습니다.',
    'IncidentManagementExtraDesc'         => '사고 관리 추가 기능은 NIST 800-61 컴퓨터 보안 사고 처리 지침을 기반으로 하며 SimpleRisk 시스템 내에서 사고 관리 기능을 제공합니다.',

    // Configure Hub - tile descriptions (customization category)
    'RedefineNamingConventionsDesc'       => 'SimpleRisk의 용어(위험, 자산, 프레임워크 등)를 사용자 인터페이스 전체에서 새로운 이름으로 변경합니다.',
    'RiskConfigurationDesc'               => '위험 점수 산정 규칙을 구성합니다. 위험 수준, 위험 감수 수준, SLA 임계값, 그리고 기존/기여 위험 공식 등을 설정할 수 있습니다.',
    'RiskAndThreatCatalogDesc'            => '드롭다운 메뉴에 사용되는 위험 및 위협 값의 카탈로그를 유지 관리합니다.',
    'AddAndRemoveValuesDesc'              => '위험 필드의 드롭다운 값을 관리합니다: 위치, 출처, 범주, 팀, 기술 등.',
    'AssetValuationDesc'                  => '자산 가치 평가 척도와 자산별 가치 평가 재정의를 구성합니다.',

    // Configure Hub - tile descriptions (users category)
    'UserManagementDesc'                  => '사용자를 추가, 편집, 비활성화 및 재설정하고 비밀번호 정책을 관리합니다.',
    'RoleManagementDesc'                  => '역할과 각 역할에 부여되는 권한을 정의합니다.',
    'TeamManagementDesc'                  => '레코드 가시성 필터링에 사용되는 팀을 생성하고 관리합니다.',
    'SeparationExtraDesc'                 => '팀 기반 분리 추가 기능을 사용하면 해당 위험이 할당된 팀의 구성원인 사용자만 위험을 볼 수 있도록 제한할 수 있습니다. SimpleRisk Core 제품에서 이 추가 기능을 사용하지 않으면 모든 사용자가 모든 위험을 볼 수 있습니다.',
    'CustomAuthenticationExtraDesc'       => '사용자 지정 인증 추가 기능은 Active Directory 및 SAML 인증을 지원합니다. SimpleRisk Core 제품에서 이 추가 기능이 없으면 SimpleRisk ID 저장소에서 새 사용자를 생성하는 방법밖에 없습니다.',
    'EncryptionExtraDesc'                 => '암호화된 데이터베이스 Extra는 임의의 AES-256비트 암호화 키를 생성하고, 이를 사용하여 중요한 텍스트를 SimpleRisk 데이터베이스에 삽입하기 전에 암호화합니다. 이를 통해 SimpleRisk 애플리케이션을 직접 사용하지 않고는 누구도 데이터를 보거나 수정할 수 없습니다.',
    'OrganizationManagementDesc'          => '조직 계층 구조 Extra를 사용하면 여러 개의 사업부를 정의할 수 있으며, 각 사업부에는 원하는 수의 팀을 포함할 수 있습니다. 이후 사용자를 여러 사업부 아래의 하나 이상의 팀에 걸쳐 할당할 수 있습니다. 이는 사용자가 연관되지 않은 팀, 사용자 및 자산을 보고 사용할 수 있는 권한에 영향을 줍니다.',

    // Configure Hub - tile descriptions (data category)
    'DeleteRisksDesc'                     => '위험을 일괄 삭제합니다. 신중하게 사용하십시오. 삭제는 영구적입니다.',
    'AuditTrailDesc'                      => '사용자 작업에 대한 시스템 감사 로그를 검색하고 내보냅니다.',
    'ImportExportExtraDesc'               => '가져오기/내보내기 추가 기능은 CSV 파일의 필드를 SimpleRisk 데이터베이스의 필드에 매핑하여 SimpleRisk로 데이터를 가져올 수 있도록 합니다. 이 기능을 사용하여 타사 스프레드시트의 감사 결과, 다른 도구의 취약점 스캔 결과, CMDB의 자산 등을 가져올 수 있습니다. 또한 이 추가 기능을 통해 위험, 완화 조치, 검토 또는 이 세 가지를 모두 포함하는 보고서를 SimpleRisk에서 CSV 파일로 내보낼 수 있습니다.',
    'JiraExtraDesc'                       => 'Jira 통합 Extra를 사용하면 사용자가 Jira 인스턴스와 양방향으로 통합할 수 있습니다. 위험을 Jira 문제에 연결하고, 해당 데이터, 상태 및 댓글을 동기화할 수 있습니다.',
    'APIExtraDesc'                        => 'API Extra를 사용하면 고객은 RESTful API를 이용하여 다른 애플리케이션과의 스크립트 기반 상호 작용을 생성함으로써 고급 자동화를 구현하고 기존 인프라를 활용할 수 있습니다.',
    'AdvancedSearchExtraDesc'             => "고급 검색 기능은 상단 바의 검색 상자를 위험, 프레임워크, 통제, 문서, 예외, 테스트, 감사, 자산 및 자산 그룹 전반에 걸친 단일 검색으로 전환하고, 검색 결과를 자세히 살펴볼 수 있는 전체 검색 페이지를 제공합니다. 이 기능은 사용자가 볼 수 있도록 허용된 레코드만 표시합니다.",
    'AssessmentsExtraDesc'                => '위험 평가 Extra를 사용하면 사용자가 연락처를 정의하고, 질문(논리 포함)을 생성하고, 설문지 템플릿으로 여러 질문을 구성하고, 설문지를 생성하여 연락처에 보내고, 설문지 결과를 확인하고, 해당 결과를 기반으로 위험을 추가하고, 시간 경과에 따른 결과를 비교하고, 외부에서 사용자 지정한 평가를 가져오고 내보내며, 위험 평가 감사 추적을 검토할 수 있습니다.',
    'ActiveAssessmentsDesc'               => '현재 진행 중인 평가를 확인하고 관리하세요.',
    'WorkflowsExtraDesc'                  => '워크플로 Extra는 SimpleRisk 내 이벤트에 대응하여 위험 관리 작업을 자동화하는 시각적인 이벤트 기반 워크플로 엔진을 제공합니다. 위험 제출, 업데이트 또는 검토와 같은 변경 시 트리거되는 워크플로를 설계하여 승인을 라우팅하고, 작업을 할당하며, 수동 개입 없이 프로세스를 계속 진행할 수 있습니다.',

    // Configure Hub - tile descriptions (frameworks category)
    'SCFExtraDesc'                        => 'Secure Controls Framework(SCF) Extra는 Secure Controls Framework와 SimpleRisk를 직접 통합하는 모듈입니다. SCF의 제어 카탈로그와 다양한 규정 준수 및 사이버 보안 프레임워크 전반에 걸친 매핑을 SimpleRisk의 거버넌스 기능으로 가져오므로, 필요한 프레임워크를 도입하고 해당 제어를 직접 만들지 않고도 관리할 수 있습니다.',

    // Configure Hub - tile descriptions (maintenance category)
    'FixReviewDatesDesc'                  => '기존 varchar 형식의 검토 날짜 열을 올바른 날짜 유형으로 마이그레이션합니다. 필요한 경우에만 표시됩니다.',
    'DatabaseUpgradeDesc'                 => 'SimpleRisk 데이터베이스 업그레이드 루틴을 수동으로 실행합니다.',

