    'QuestionnaireDraftAuditLogViaApi' => '사용자 "{$user_name}"이(가) API를 통해 연락처 "{$contact_name}"의 설문지 "{$questionnaire_name}"을(를) 임시 저장했습니다.',
    // Bad-input response for the questionnaire risk-list endpoints, which
