    'SoaLegendInherited' => '해당 제어는 적용 범위에 포함되지만, 이 조직이 아닌 제3자(클라우드 공급자, 모회사, 외주 기능)가 운영합니다. 공급자는 근거 옆에 표시됩니다.',
