    'ApplicabilityAppliesToSelected' => '이 페이지에서 선택한 제어 {$n}개에 대해 기록됩니다.',
    'ApplicabilityAppliesToAllFiltered' => '다른 페이지의 제어를 포함하여 현재 필터와 일치하는 모든 제어 {$n}개에 대해 기록됩니다.',
    // Per-state hints under the segmented control. The "applicable" one is the
