    'ApplicabilityNotApplicableHint' => '이 프레임워크의 범위에서 통제 항목을 제외하려면, 그 이유와 함께 서면으로 된 근거를 제시해야 합니다.',
    'ApplicabilityInheritedHint' => '다른 주체가 귀하를 대신하여 이 제어를 수행합니다. 해당 주체의 이름과 수행하는 작업을 입력하세요.',
    'ApplicabilityNarrativeHint' => '적용 가능성 기술서에 표시됩니다. 감사자가 결정을 수용하는 데 필요한 내용을 작성하세요.',
    'ApplicabilityProviderHint' => '제어를 수행하는 조직입니다(예: 클라우드 공급자, 관리형 서비스, 모회사).',
