    'QuestionnaireQuestionDeleteRequiresJavaScript' => '질문을 삭제하려면 브라우저에서 JavaScript가 활성화되어 있어야 합니다.',
    // Initiate Audits' bulk bar (SR-2234): the header checkbox already
