    'SelectAllTooManyMatches' => '현재 필터와 일치하는 {$noun}이(가) {$max}개를 초과합니다. 필터를 좁힌 후 다시 시도하세요.',
    // POST /documents/batch-delete (batch_delete_document_api(), includes/api.php):
