    'DocumentsDeletedTruncated' => '선택한 문서 중 첫 번째 {$limit}개만 삭제되었습니다. 나머지를 삭제하려면 작업을 다시 수행하세요.',
    // POST /exceptions/batch-delete-ids (batch_delete_exceptions_by_ids_api()) --
