    'ExceptionsDeletedTruncated' => '선택한 예외 중 첫 번째 {$limit}개만 삭제되었습니다. 나머지를 삭제하려면 작업을 다시 수행하세요.',
    // POST /risks/batch-close (closeRiskBatch(), includes/api.php): whole-batch
