    'ManagedByYourAdministrator' => '이 세부 정보는 관리자가 관리합니다. 변경이 필요한 사항이 있으면 관리자에게 문의하세요.',
    'MultiFactorAuthenticationHint' => '계정 보안을 강화하기 위해 로그인 절차에 두 번째 단계를 추가하세요.',
    'ChangingPasswordSignsOutEverywhere' => '비밀번호를 변경하면 다른 모든 곳에서 로그아웃됩니다.',
    'APIKeyHint' => 'SimpleRisk API에 대한 자체 스크립트 및 통합 기능을 인증하는 데 사용됩니다.',
    'ResetDisplaySettingsHint' => '사용자 지정 열 선택을 기본값으로 재설정합니다.',
