    'AssetScoring' => '자산 점수 산정',
    'AssetScoringSettingsHint' => '각 자산은 기밀성, 무결성, 가용성에 대해 낮음, 보통 또는 높음으로 평가되며, 기밀성은 대신 해당 없음일 수 있고 이 경우 두 결과 모두에서 제외됩니다. FIPS 분류는 세 평가 중 가장 높은 수준입니다. 가중 점수는 세 수준 값의 가중 평균이며, 구간 임계값에 따라 이 점수가 낮음, 보통 또는 높음 구간으로 결정됩니다. 이 설정을 변경하면 모든 자산의 점수가 즉시 다시 산정됩니다.',
