    'LevelValues' => '수준 값',
    'AssetScoringLevelValuesHint' => '각 평가가 가중 점수에 기여하는 숫자입니다. 0보다 크고 100 이하이며 소수점 둘째 자리까지 입력할 수 있고, 낮음 < 보통 < 높음 순이어야 합니다. 기본 값은 낮음 1, 보통 2, 높음 3입니다.',
    'BandThresholds' => '구간 임계값',
    'AssetScoringBandThresholdsHint' => '가중 점수가 임계값 이상이면 해당 구간에 속하고, 보통 임계값 미만이면 낮음입니다. 보통은 낮음 값보다 큰 값에서 시작해야 하며, 높음은 보통보다 큰 값에서 시작하되 높음 값을 초과할 수 없습니다.',
