    // SR-115: HTTP Strict Transport Security (HSTS)
    'EnableHSTS' => 'HTTP Strict Transport Security(HSTS) 활성화',
    'EnableHSTSHelp' => '이 헤더는 브라우저가 지정된 최대 사용 기간 동안 SimpleRisk에 HTTPS를 통해서만 연결하도록 합니다. 이 기능은 해당 사이트에서 HTTPS가 안정적으로 작동하는 경우에만 활성화하십시오. 이 헤더를 받은 브라우저는 일반 HTTP 연결을 거부하며, 최대 사용 기간이 만료될 때까지 손상된 인증서를 우회할 수 없습니다. 처음에는 300초와 같이 짧은 최대 사용 기간으로 시작하고 HTTPS가 확인되면 값을 높이십시오.',
    'HSTSMaxAge' => 'HSTS 최대 수명(초)',
